        // Detach so we can attach updated entity
        _context.Entry(existing).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updatedStudent = new Student
        {
            ID = existing.ID,
            FirstMidName = "Updated",
            LastName = "Alexander",
            EnrollmentDate = existing.EnrollmentDate
        };

        var result = _controller.Edit(updatedStudent);

