        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_MinValueDate_ReturnsViewWithError()
    {
        var existing = _context.Students.First();
        _context.Entry(existing).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updatedStudent = new Student
        {
            ID = existing.ID,
            FirstMidName = existing.FirstMidName,
            LastName = existing.LastName,
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Edit(updatedStudent) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

