using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        TestHelpers.DrainNotificationQueue();
        _context = TestHelpers.CreateSeededContext();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns((string?)null);
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        TestHelpers.DrainNotificationQueue();
    }

    // === Index ===

    [Fact]
    public void Index_ReturnsViewWithCourses()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var courses = Assert.IsType<List<Course>>(result.Model);
        Assert.Single(courses);
        Assert.Equal("Chemistry", courses[0].Title);
    }

    // === Details ===

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var courseId = _context.Courses.First().CourseID;

        var result = _controller.Details(courseId) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
    }

    // === Create GET ===

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentSelectList()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    // === Create POST ===

    [Fact]
    public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 2000,
            Title = "Physics",
            Credits = 4,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var result = _controller.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidCourse_SavesInDatabase()
    {
        var course = new Course
        {
            CourseID = 2000,
            Title = "Physics",
            Credits = 4,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        _controller.Create(course, null!);

        Assert.Equal(2, _context.Courses.Count());
        var saved = _context.Courses.First(c => c.Title == "Physics");
        Assert.Equal(2000, saved.CourseID);
        Assert.Equal(4, saved.Credits);
    }

    [Fact]
    public void Create_Post_InvalidExtension_ReturnsViewWithError()
    {
        var course = new Course
        {
            CourseID = 2001,
            Title = "Biology",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var mockFile = CreateMockFile("test.exe", 100);

        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains("valid image file", errors[0].ErrorMessage);
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        var course = new Course
        {
            CourseID = 2002,
            Title = "Art",
            Credits = 2,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var mockFile = CreateMockFile("test.jpg", 6 * 1024 * 1024); // 6MB

        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains("5MB", errors[0].ErrorMessage);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_AllowedExtensions_AreAccepted(string extension)
    {
        var course = new Course
        {
            CourseID = 3000 + Math.Abs(extension.GetHashCode() % 1000),
            Title = $"Course{extension}",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var mockFile = CreateMockFile($"test{extension}", 1024);

        var result = _controller.Create(course, mockFile.Object);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 5000, Title = "", Credits = 3 };

        var result = _controller.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Post_SendsNotification()
    {
        TestHelpers.DrainNotificationQueue();
        var course = new Course
        {
            CourseID = 4000,
            Title = "TestCourse",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        _controller.Create(course, null!);

        var notification = _controller.notificationService.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course", notification.EntityType);
        Assert.Contains("CREATE", notification.Operation);
    }

    // === Edit GET ===

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null, null!);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(99999, null!);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCourse()
    {
        var courseId = _context.Courses.First().CourseID;

        var result = _controller.Edit(courseId, null!) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
    }

    // === Edit POST ===

    [Fact]
    public void Edit_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        var existing = _context.Courses.First();
        _context.Entry(existing).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updated = new Course
        {
            CourseID = existing.CourseID,
            Title = "Advanced Chemistry",
            Credits = 4,
            DepartmentID = existing.DepartmentID
        };

        var result = _controller.Edit(updated, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
