using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        TestHelpers.DrainNotificationQueue();
        _context = TestHelpers.CreateSeededContext();
        _controller = new DepartmentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        TestHelpers.DrainNotificationQueue();
    }

    // === Index ===

    [Fact]
    public void Index_ReturnsViewWithDepartments()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var departments = Assert.IsType<List<Department>>(result.Model);
        Assert.Single(departments);
        Assert.Equal("Engineering", departments[0].Name);
    }

    // === Details ===

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        var deptId = _context.Departments.First().DepartmentID;

        var result = _controller.Details(deptId) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
        Assert.Equal(350000m, dept.Budget);
    }

    // === Create GET ===

    [Fact]
    public void Create_Get_ReturnsViewWithInstructorSelectList()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.InstructorID);
    }

    // === Create POST ===

    [Fact]
    public void Create_Post_ValidDepartment_RedirectsToIndex()
    {
        var department = new Department
        {
            Name = "Mathematics",
            Budget = 100000m,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = _context.Instructors.First().ID
        };

        var result = _controller.Create(department);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidDepartment_SavesInDatabase()
    {
        var department = new Department
        {
            Name = "Mathematics",
            Budget = 100000m,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = _context.Instructors.First().ID
        };

        _controller.Create(department);

        Assert.Equal(2, _context.Departments.Count());
        var saved = _context.Departments.First(d => d.Name == "Mathematics");
        Assert.Equal(100000m, saved.Budget);
    }

    [Fact]
    public void Create_Post_SendsNotification()
    {
        TestHelpers.DrainNotificationQueue();
        var department = new Department
        {
            Name = "Science",
            Budget = 200000m,
            StartDate = DateTime.Parse("2010-01-01"),
            InstructorID = _context.Instructors.First().ID
        };

        _controller.Create(department);

        var notification = _controller.notificationService.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department", notification.EntityType);
        Assert.Contains("CREATE", notification.Operation);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department
        {
            Name = "",
            Budget = 0,
            StartDate = DateTime.Today
        };

        var result = _controller.Create(dept) as ViewResult;

        Assert.NotNull(result);
    }

    // === Edit GET ===

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithDepartment()
    {
        var deptId = _context.Departments.First().DepartmentID;

        var result = _controller.Edit(deptId) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
    }

    // === Edit POST ===

    [Fact]
    public void Edit_Post_ValidDepartment_RedirectsToIndex()
    {
        var existing = _context.Departments.First();
        _context.Entry(existing).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updated = new Department
        {
            DepartmentID = existing.DepartmentID,
            Name = "Updated Engineering",
            Budget = 400000m,
            StartDate = existing.StartDate,
            InstructorID = existing.InstructorID
        };

        var result = _controller.Edit(updated);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "",
            Budget = 0,
            StartDate = DateTime.Today
        };

        var result = _controller.Edit(dept) as ViewResult;

        Assert.NotNull(result);
    }

    // === Delete GET ===

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithDepartment()
    {
        var deptId = _context.Departments.First().DepartmentID;

        var result = _controller.Delete(deptId) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
    }

    // === DeleteConfirmed ===

    [Fact]
    public void DeleteConfirmed_RemovesDepartmentAndRedirects()
    {
        // Need to remove courses first (FK constraint in InMemory)
        var courses = _context.Courses.ToList();
        _context.Courses.RemoveRange(courses);
        _context.SaveChanges();

        var deptId = _context.Departments.First().DepartmentID;

        var result = _controller.DeleteConfirmed(deptId);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Empty(_context.Departments);
    }

    [Fact]
    public void DeleteConfirmed_SendsDeleteNotification()
    {
        TestHelpers.DrainNotificationQueue();
        var courses = _context.Courses.ToList();
        _context.Courses.RemoveRange(courses);
        _context.SaveChanges();

        var deptId = _context.Departments.First().DepartmentID;

        _controller.DeleteConfirmed(deptId);

        var notification = _controller.notificationService.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department", notification.EntityType);
        Assert.Contains("DELETE", notification.Operation);
    }
}

