public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        TestHelpers.DrainNotificationQueue();
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new NotificationsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        TestHelpers.DrainNotificationQueue();
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var value = result.Value as dynamic;
        Assert.NotNull(value);
        // Check the JSON contains success = true and count = 0
        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
        Assert.Contains("\"success\":true", json);
        Assert.Contains("\"count\":0", json);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        // Send some notifications via the controller's notification service
        _controller.notificationService.SendNotification("Student", "1", "John", EntityOperation.CREATE, "Admin");
        _controller.notificationService.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "Admin");

        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
        Assert.Contains("\"success\":true", json);
        Assert.Contains("\"count\":2", json);
    }

    [Fact]
    public void GetNotifications_Max10Notifications()
    {
        // Send 15 notifications
        for (int i = 0; i < 15; i++)
        {
            _controller.notificationService.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
        }

        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
        Assert.Contains("\"count\":10", json);
    }

    [Fact]
    public void GetNotifications_LeavesRemainingInQueue()
    {
        // Send 12 notifications
        for (int i = 0; i < 12; i++)
        {
            _controller.notificationService.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
        }

        // First call gets 10
        _controller.GetNotifications();

        // Second call should get the remaining 2
        var result = _controller.GetNotifications();
        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
        Assert.Contains("\"count\":2", json);
    }

    [Fact]
    public void MarkAsRead_ReturnsJsonSuccess()
    {
        var result = _controller.MarkAsRead(1);

        Assert.NotNull(result);
        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
        Assert.Contains("\"success\":true", json);
    }

    [Fact]
    public void MarkAsRead_DifferentIds_AllReturnSuccess()
    {
        var result1 = _controller.MarkAsRead(1);
        var result2 = _controller.MarkAsRead(999);

        var json1 = System.Text.Json.JsonSerializer.Serialize(result1.Value);
        var json2 = System.Text.Json.JsonSerializer.Serialize(result2.Value);
        Assert.Contains("\"success\":true", json1);
        Assert.Contains("\"success\":true", json2);
    }

    [Fact]
    public void Index_ReturnsView()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }
}

