using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveStudent()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-01-01")
        };

        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.First();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("Student", retrieved.LastName);
        Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveInstructor()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Instructor",
            HireDate = DateTime.Parse("2020-01-01")
        };

        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.First();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("Instructor", retrieved.LastName);
        Assert.Equal(DateTime.Parse("2020-01-01"), retrieved.HireDate);
    }

    [Fact]
    public void SchoolContext_CanAddCourseWithDepartment()
    {
        var dept = new Department
        {
            Name = "Science",
            Budget = 200000m,
            StartDate = DateTime.Today
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 5000,
            Title = "Physics",
            Credits = 4,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Include(c => c.Department).First();
        Assert.Equal("Physics", retrieved.Title);
        Assert.Equal(4, retrieved.Credits);
        Assert.Equal("Science", retrieved.Department.Name);
    }

    [Fact]
    public void SchoolContext_CanAddEnrollment()
    {
        var student = new Student
        {
            FirstMidName = "En",
            LastName = "Roll",
            EnrollmentDate = DateTime.Today
        };
        _context.Students.Add(student);

        var dept = new Department { Name = "Test", Budget = 0, StartDate = DateTime.Today };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 6000, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = Grade.B
        };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments.Include(e => e.Student).Include(e => e.Course).First();
        Assert.Equal("Roll", retrieved.Student.LastName);
        Assert.Equal("TestCourse", retrieved.Course.Title);
        Assert.Equal(Grade.B, retrieved.Grade);
    }

    [Fact]
    public void SchoolContext_CourseAssignment_CompositeKey()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Key",
            LastName = "Test",
            HireDate = DateTime.Today
        };
        _context.Instructors.Add(instructor);

        var dept = new Department { Name = "Dept", Budget = 0, StartDate = DateTime.Today };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 7000, Title = "Key Course", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var ca = new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments.First();
        Assert.Equal(instructor.ID, retrieved.InstructorID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
    }

    [Fact]
    public void SchoolContext_OfficeAssignment_OneToOne()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Office",
            LastName = "Test",
            HireDate = DateTime.Today
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var office = new OfficeAssignment
        {
            InstructorID = instructor.ID,
            Location = "Room 101"
        };
        _context.OfficeAssignments.Add(office);
        _context.SaveChanges();

        var retrieved = _context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => i.ID == instructor.ID);
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void SchoolContext_DbSetsAreAccessible()
    {
        Assert.NotNull(_context.Courses);
        Assert.NotNull(_context.Students);
        Assert.NotNull(_context.Instructors);
        Assert.NotNull(_context.Departments);
        Assert.NotNull(_context.Enrollments);
        Assert.NotNull(_context.OfficeAssignments);
        Assert.NotNull(_context.CourseAssignments);
        Assert.NotNull(_context.Notifications);
        Assert.NotNull(_context.People);
    }

    [Fact]
    public void SchoolContext_CanAddNotification()
    {
        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test notification",
            CreatedAt = DateTime.Now,
            CreatedBy = "System",
            IsRead = false
        };
        _context.Notifications.Add(notification);
        _context.SaveChanges();

        var retrieved = _context.Notifications.First();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("1", retrieved.EntityId);
        Assert.Equal("CREATE", retrieved.Operation);
        Assert.Equal("Test notification", retrieved.Message);
        Assert.Equal("System", retrieved.CreatedBy);
        Assert.False(retrieved.IsRead);
    }
}

