1. using ContosoUniversity.Models;
2. using ContosoUniversity.Services;
3. 
4. namespace ContosoUniversity.Tests;
5. 
6. public class NotificationServiceTests : IDisposable
7. {
8.     private readonly NotificationService _service;
9. 
10.     public NotificationServiceTests()
11.     {
12.         // Drain the static queue before each test
13.         TestHelpers.DrainNotificationQueue();
14.         _service = new NotificationService();
15.     }
16. 
17.     public void Dispose()
18.     {
19.         _service.Dispose();
20.         TestHelpers.DrainNotificationQueue();
21.     }
22. 
23.     [Fact]
24.     public void SendNotification_WithDisplayName_EnqueuesCorrectMessage()
25.     {
26.         _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
27. 
28.         var notification = _service.ReceiveNotification();
29. 
30.         Assert.NotNull(notification);
31.         Assert.Equal("Student", notification.EntityType);
32.         Assert.Equal("1", notification.EntityId);
33.         Assert.Equal("CREATE", notification.Operation);
34.         Assert.Equal("New Student 'John Doe' has been created", notification.Message);
35.         Assert.Equal("Admin", notification.CreatedBy);
36.         Assert.False(notification.IsRead);
37.     }
38. 
39.     [Fact]
40.     public void SendNotification_WithoutDisplayName_UsesIdInMessage()
41.     {
42.         _service.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");
43. 
44.         var notification = _service.ReceiveNotification();
45. 
46.         Assert.NotNull(notification);
47.         Assert.Equal("Course", notification.EntityType);
48.         Assert.Equal("42", notification.EntityId);
49.         Assert.Equal("UPDATE", notification.Operation);
50.         Assert.Equal("Course (ID: 42) has been updated", notification.Message);
51.         Assert.Equal("Teacher", notification.CreatedBy);
52.     }
53. 
54.     [Fact]
55.     public void SendNotification_WithNullUserName_DefaultsToSystem()
56.     {
57.         _service.SendNotification("Department", "5", EntityOperation.DELETE);
58. 
59.         var notification = _service.ReceiveNotification();
60. 
61.         Assert.NotNull(notification);
62.         Assert.Equal("System", notification.CreatedBy);
63.     }
64. 
65.     [Fact]
66.     public void SendNotification_Delete_GeneratesDeleteMessage()
67.     {
68.         _service.SendNotification("Student", "10", "Jane Smith", EntityOperation.DELETE, "Admin");
69. 
70.         var notification = _service.ReceiveNotification();
71. 
72.         Assert.NotNull(notification);
73.         Assert.Equal("DELETE", notification.Operation);
74.         Assert.Equal("Student 'Jane Smith' has been deleted", notification.Message);
75.     }
76. 
77.     [Fact]
78.     public void SendNotification_SetsCreatedAtToRecentTime()
79.     {
80.         var before = DateTime.Now.AddSeconds(-1);
81. 
82.         _service.SendNotification("Student", "1", EntityOperation.CREATE);
83. 
84.         var notification = _service.ReceiveNotification();
85.         Assert.NotNull(notification);
86.         Assert.True(notification.CreatedAt >= before, "CreatedAt should be recent");
87.         Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1), "CreatedAt should not be in the future");
88.     }
89. 
90.     [Fact]
91.     public void ReceiveNotification_EmptyQueue_ReturnsNull()
92.     {
93.         var result = _service.ReceiveNotification();
94. 
95.         Assert.Null(result);
96.     }
97. 
98.     [Fact]
99.     public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
100.     {
101.         _service.SendNotification("A", "1", EntityOperation.CREATE);
102.         _service.SendNotification("B", "2", EntityOperation.UPDATE);
103.         _service.SendNotification("C", "3", EntityOperation.DELETE);
104. 
105.         var first = _service.ReceiveNotification();
106.         var second = _service.ReceiveNotification();
107.         var third = _service.ReceiveNotification();
108.         var fourth = _service.ReceiveNotification();
109. 
110.         Assert.NotNull(first);
111.         Assert.Equal("A", first.EntityType);
112.         Assert.NotNull(second);
113.         Assert.Equal("B", second.EntityType);
114.         Assert.NotNull(third);
115.         Assert.Equal("C", third.EntityType);
116.         Assert.Null(fourth);
117.     }
118. 
119.     [Fact]
120.     public void MarkAsRead_DoesNotThrow()
121.     {
122.         // MarkAsRead is a no-op but should not throw
123.         var exception = Record.Exception(() => _service.MarkAsRead(999));
124. 
125.         Assert.Null(exception);
126.     }
127. 
128.     [Fact]
129.     public void SendNotification_WithEmptyDisplayName_FallsBackToId()
130.     {
131.         _service.SendNotification("Student", "7", "", EntityOperation.CREATE, "Admin");
132. 
133.         var notification = _service.ReceiveNotification();
134. 
135.         Assert.NotNull(notification);
136.         // Empty string is treated as whitespace, falls back to ID form
137.         Assert.Equal("New Student (ID: 7) has been created", notification.Message);
138.     }
139. 
140.     [Fact]
141.     public void SendNotification_WithWhitespaceDisplayName_FallsBackToId()
142.     {
143.         _service.SendNotification("Student", "7", "   ", EntityOperation.CREATE, "Admin");
144. 
145.         var notification = _service.ReceiveNotification();
146. 
147.         Assert.NotNull(notification);
148.         Assert.Equal("New Student (ID: 7) has been created", notification.Message);
149.     }
150. 
151.     [Fact]
152.     public void SendNotification_OverloadWithoutDisplayName_CallsFullOverload()
153.     {
154.         _service.SendNotification("Instructor", "3", EntityOperation.UPDATE, "System");
155. 
156.         var notification = _service.ReceiveNotification();
157. 
158.         Assert.NotNull(notification);
159.         Assert.Equal("Instructor (ID: 3) has been updated", notification.Message);
160.     }
161. 
162.     [Fact]
163.     public void Dispose_DoesNotThrow()
164.     {
165.         var service = new NotificationService();
166. 
167.         var exception = Record.Exception(() => service.Dispose());
168. 
169.         Assert.Null(exception);
170.     }
171. 
172.     [Fact]
173.     public void SendNotification_QueueEnforcesMaxLength()
174.     {
175.         // The max queue length is 500. Send 510 notifications.
176.         for (int i = 0; i < 510; i++)
177.         {
178.             _service.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
179.         }
180. 
181.         // Drain the queue and count
182.         int count = 0;
183.         while (_service.ReceiveNotification() != null)
184.         {
185.             count++;
186.         }
187. 
188.         // Should be <= 500 due to the cap enforcement
189.         Assert.True(count <= 500, $"Queue should have at most 500 items but had {count}");
190.         Assert.True(count > 0, "Queue should not be empty");
191.     }
192. 
193.     [Fact]
194.     public void SendNotification_NullDisplayName_UsesIdInMessage()
195.     {
196.         _service.SendNotification("Course", "99", (string?)null, EntityOperation.UPDATE, "Admin");
197. 
198.         var notification = _service.ReceiveNotification();
199. 
200.         Assert.NotNull(notification);
201.         Assert.Equal("Course (ID: 99) has been updated", notification.Message);
202.     }
203. }
204.

