 using ContosoUniversity.Models;
 using ContosoUniversity.Services;

 namespace ContosoUniversity.Tests;

 public class NotificationServiceTests : IDisposable
 {
     private readonly NotificationService _service;

     public NotificationServiceTests()
     {
         // Drain the static queue before each test
         TestHelpers.DrainNotificationQueue();
         _service = new NotificationService();
     }

     public void Dispose()
     {
         _service.Dispose();
         TestHelpers.DrainNotificationQueue();
     }

     [Fact]
     public void SendNotification_WithDisplayName_EnqueuesCorrectMessage()
     {
         _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         Assert.Equal("Student", notification.EntityType);
         Assert.Equal("1", notification.EntityId);
         Assert.Equal("CREATE", notification.Operation);
         Assert.Equal("New Student 'John Doe' has been created", notification.Message);
         Assert.Equal("Admin", notification.CreatedBy);
         Assert.False(notification.IsRead);
     }

     [Fact]
     public void SendNotification_WithoutDisplayName_UsesIdInMessage()
     {
         _service.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         Assert.Equal("Course", notification.EntityType);
         Assert.Equal("42", notification.EntityId);
         Assert.Equal("UPDATE", notification.Operation);
         Assert.Equal("Course (ID: 42) has been updated", notification.Message);
         Assert.Equal("Teacher", notification.CreatedBy);
     }

     [Fact]
     public void SendNotification_WithNullUserName_DefaultsToSystem()
     {
         _service.SendNotification("Department", "5", EntityOperation.DELETE);

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         Assert.Equal("System", notification.CreatedBy);
     }

     [Fact]
     public void SendNotification_Delete_GeneratesDeleteMessage()
     {
         _service.SendNotification("Student", "10", "Jane Smith", EntityOperation.DELETE, "Admin");

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         Assert.Equal("DELETE", notification.Operation);
         Assert.Equal("Student 'Jane Smith' has been deleted", notification.Message);
     }

     [Fact]
     public void SendNotification_SetsCreatedAtToRecentTime()
     {
         var before = DateTime.Now.AddSeconds(-1);

         _service.SendNotification("Student", "1", EntityOperation.CREATE);

         var notification = _service.ReceiveNotification();
         Assert.NotNull(notification);
         Assert.True(notification.CreatedAt >= before, "CreatedAt should be recent");
         Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1), "CreatedAt should not be in the future");
     }

     [Fact]
     public void ReceiveNotification_EmptyQueue_ReturnsNull()
     {
         var result = _service.ReceiveNotification();

         Assert.Null(result);
     }

     [Fact]
     public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
     {
         _service.SendNotification("A", "1", EntityOperation.CREATE);
         _service.SendNotification("B", "2", EntityOperation.UPDATE);
         _service.SendNotification("C", "3", EntityOperation.DELETE);

         var first = _service.ReceiveNotification();
         var second = _service.ReceiveNotification();
         var third = _service.ReceiveNotification();
         var fourth = _service.ReceiveNotification();

         Assert.NotNull(first);
         Assert.Equal("A", first.EntityType);
         Assert.NotNull(second);
         Assert.Equal("B", second.EntityType);
         Assert.NotNull(third);
         Assert.Equal("C", third.EntityType);
         Assert.Null(fourth);
     }

     [Fact]
     public void MarkAsRead_DoesNotThrow()
     {
         // MarkAsRead is a no-op but should not throw
         var exception = Record.Exception(() => _service.MarkAsRead(999));

         Assert.Null(exception);
     }

     [Fact]
     public void SendNotification_WithEmptyDisplayName_FallsBackToId()
     {
         _service.SendNotification("Student", "7", "", EntityOperation.CREATE, "Admin");

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         // Empty string is treated as whitespace, falls back to ID form
         Assert.Equal("New Student (ID: 7) has been created", notification.Message);
     }

     [Fact]
     public void SendNotification_WithWhitespaceDisplayName_FallsBackToId()
     {
         _service.SendNotification("Student", "7", "   ", EntityOperation.CREATE, "Admin");

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         Assert.Equal("New Student (ID: 7) has been created", notification.Message);
     }

     [Fact]
     public void SendNotification_OverloadWithoutDisplayName_CallsFullOverload()
     {
         _service.SendNotification("Instructor", "3", EntityOperation.UPDATE, "System");

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         Assert.Equal("Instructor (ID: 3) has been updated", notification.Message);
     }

     [Fact]
     public void Dispose_DoesNotThrow()
     {
         var service = new NotificationService();

         var exception = Record.Exception(() => service.Dispose());

         Assert.Null(exception);
     }

     [Fact]
     public void SendNotification_QueueEnforcesMaxLength()
     {
         // The max queue length is 500. Send 510 notifications.
         for (int i = 0; i < 510; i++)
         {
             _service.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
         }

         // Drain the queue and count
         int count = 0;
         while (_service.ReceiveNotification() != null)
         {
             count++;
         }

         // Should be <= 500 due to the cap enforcement
         Assert.True(count <= 500, $"Queue should have at most 500 items but had {count}");
         Assert.True(count > 0, "Queue should not be empty");
     }

     [Fact]
     public void SendNotification_NullDisplayName_UsesIdInMessage()
     {
         _service.SendNotification("Course", "99", (string?)null, EntityOperation.UPDATE, "Admin");

         var notification = _service.ReceiveNotification();

         Assert.NotNull(notification);
         Assert.Equal("Course (ID: 99) has been updated", notification.Message);
     }
 }

