         var saved = _context.Instructors.First(i => i.LastName == "Smith");
         Assert.Equal("John", saved.FirstMidName);
         Assert.Equal(DateTime.Parse("2020-01-01"), saved.HireDate);
     }

     [Fact]
     public void Create_Post_WithSelectedCourses_CreatesCourseAssignments()
     {
         var courseId = _context.Courses.First().CourseID;
         var instructor = new Instructor
         {
             FirstMidName = "Jane",
             LastName = "Jones",
             HireDate = DateTime.Parse("2020-01-01")
         };

         _controller.Create(instructor, new[] { courseId.ToString() });

         var saved = _context.Instructors.First(i => i.LastName == "Jones");
         Assert.NotNull(saved.CourseAssignments);
         Assert.Single(saved.CourseAssignments);
     }

     [Fact]
     public void Create_Post_InvalidModelState_ReturnsView()
