         Assert.NotNull(result);
         var instructor = Assert.IsType<Instructor>(result.Model);
         Assert.Equal("Abercrombie", instructor.LastName);
     }

     // === DeleteConfirmed ===

     [Fact]
     public void DeleteConfirmed_RemovesInstructorAndRedirects()
     {
         var instructor = _context.Instructors.First();
         // Need to clear the department FK reference
         var dept = _context.Departments.FirstOrDefault(d => d.InstructorID == instructor.ID);
         if (dept != null)
         {
             dept.InstructorID = null;
             _context.SaveChanges();
         }

         var result = _controller.DeleteConfirmed(instructor.ID);

         var redirect = Assert.IsType<RedirectToActionResult>(result);
         Assert.Equal("Index", redirect.ActionName);
         Assert.Empty(_context.Instructors);
     }

     [Fact]
     public void DeleteConfirmed_ClearsDepartmentAdministrator()
     {
         var instructor = _context.Instructors.First();
         var dept = _context.Departments.First(d => d.InstructorID == instructor.ID);
         Assert.NotNull(dept.InstructorID);

         _controller.DeleteConfirmed(instructor.ID);

         // Reload department
         var updatedDept = _context.Departments.First(d => d.DepartmentID == dept.DepartmentID);
         Assert.Null(updatedDept.InstructorID);
     }

     [Fact]
     public void DeleteConfirmed_SendsDeleteNotification()
     {
         TestHelpers.DrainNotificationQueue();
         var notificationSvc = new Services.NotificationService();
         var instructor = _context.Instructors.First();

         _controller.DeleteConfirmed(instructor.ID);

         var notification = notificationSvc.ReceiveNotification();
         Assert.NotNull(notification);
         Assert.Equal("Instructor", notification.EntityType);
         Assert.Contains("DELETE", notification.Operation);
     }
 }

