/// </summary>
public class BoundaryAndGapTests : IDisposable
{
    public BoundaryAndGapTests()
    {
        TestHelpers.DrainNotificationQueue();
    }

    public void Dispose()
    {
        TestHelpers.DrainNotificationQueue();
    }

    // === PaginatedList Boundary Tests ===

    [Fact]
    public void PaginatedList_TotalPages_UsesCeilingNotFloor()
    {
        // 21 items, 10 per page: ceil(2.1) = 3, floor(2.1) = 2
        var source = Enumerable.Range(1, 21).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(3, result.TotalPages); // Must be 3, not 2
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void PaginatedList_HasNextPage_AtLastPage_PageIndexEqualsTotalPages()
    {
        var source = Enumerable.Range(1, 30).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.False(result.HasNextPage); // PageIndex == TotalPages, so < is false
    }

    [Fact]
    public void PaginatedList_HasNextPage_OneBeforeLast_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 30).AsQueryable();

        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.Equal(2, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.True(result.HasNextPage); // 2 < 3
    }

    [Fact]
    public void PaginatedList_HasPreviousPage_AtPage2_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 30).AsQueryable();

        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.True(result.HasPreviousPage); // 2 > 1
    }

    // === Students Controller Date Boundary Tests ===

    [Fact]
