+
+        var result = controller.Create(student) as ViewResult;
+
+        Assert.NotNull(result);
+        Assert.False(controller.ModelState.IsValid);
+        Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
+    }
+
+    [Fact]
+    public void Students_Index_UnknownSortOrder_DefaultsToLastNameAscending()
+    {
+        using var context = TestHelpers.CreateSeededContext();
+        // Add second student with a later LastName
+        context.Students.Add(new Student
+        {
+            FirstMidName = "Zach",
+            LastName = "Zenith",
+            EnrollmentDate = DateTime.Today
+        });
+        context.SaveChanges();
+        using var controller = new StudentsController(context);
+
+        var result = controller.Index("unknown_sort", null, null, null) as ViewResult;
+
+        Assert.NotNull(result);
+        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
+        Assert.Equal(2, model.Count);
+        Assert.Equal("Alexander", model[0].LastName); // Default ascending by LastName
+        Assert.Equal("Zenith", model[1].LastName);
+    }
