+    // === Notifications Controller Boundary Tests ===
+
+    [Fact]
+    public void Notifications_GetNotifications_Exactly9Sent_Returns9()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+        using var controller = new NotificationsController(context);
