+    // === NotificationService - Unknown Operation Enum Test ===
+
+    [Fact]
+    public void NotificationService_UnknownOperation_GeneratesFallbackMessage()
+    {
+        var svc = new Services.NotificationService();
+        svc.SendNotification("Widget", "42", "MyWidget", (EntityOperation)999, "Admin");
+
+        var notification = svc.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("Widget", notification.EntityType);
+        Assert.Equal("42", notification.EntityId);
+        Assert.Equal("999", notification.Operation);
+        Assert.Contains("Widget 'MyWidget'", notification.Message);
+        Assert.Contains("999", notification.Message);
+    }
+
