+        Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
+    }
+
+    // === Helper ===
+
+    private static Mock<IFormFile> CreateMockFile(string fileName, long size)
+    {
+        var mockFile = new Mock<IFormFile>();
+        mockFile.Setup(f => f.FileName).Returns(fileName);
+        mockFile.Setup(f => f.Length).Returns(size);
+        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));
+        return mockFile;
+    }
+}
